<style>
:root{--ink:#182033;--muted:#798196;--line:#e8eaf0;--blue:#21bde1;--blue-deep:#168cd3}*{box-sizing:border-box}body{margin:0;background:linear-gradient(120deg,#dce7ff,#f7f5ef 52%,#e2dfff);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}a{text-decoration:none;color:inherit}.admin-app{width:100%;min-height:100vh;background:#fff;display:flex}.admin-sidebar{width:245px;flex:none;border-right:1px solid var(--line);padding:24px 17px 18px;display:flex;flex-direction:column;background:linear-gradient(180deg,#fff,#fbfbfd)}.admin-logo{font-size:22px;font-weight:800;letter-spacing:-.06em;padding:5px 8px 29px;display:flex;align-items:center;gap:8px}.admin-logo-mark{display:flex;align-items:end;gap:2px;height:23px}.admin-logo-mark i{display:block;width:5px;border-radius:2px;background:#18b9dc}.admin-logo-mark i:nth-child(1){height:14px}.admin-logo-mark i:nth-child(2){height:22px}.admin-logo-mark i:nth-child(3){height:17px}.admin-nav-label{font-size:11px;letter-spacing:.07em;color:#9ba1af;margin:16px 9px 8px;text-transform:uppercase}.admin-nav a{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:8px;font-size:14px;margin:3px 0;color:#343b4b}.admin-nav a.active,.admin-nav a:hover{background:#bceff7;font-weight:700}.admin-icon{width:18px;text-align:center}.admin-badge{margin-left:auto;border:1px solid #e0e3e9;border-radius:5px;background:#fff;padding:2px 7px;font-size:11px}.admin-sidebar-bottom{margin-top:auto;border-top:1px solid var(--line);padding-top:15px;display:flex;align-items:center;gap:9px}.admin-avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#f6c9b7,#74463a);color:#fff;font-weight:700}.admin-user-name{font-weight:700;font-size:13px}.admin-user-role{font-size:11px;color:var(--muted);margin-top:2px}.admin-main{min-width:0;flex:1;display:flex;flex-direction:column}.admin-topbar{height:66px;flex:none;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 30px;gap:15px}.admin-top-title{font-size:16px;font-weight:600}.admin-search{margin-left:auto;width:min(300px,35vw);height:38px;border:1px solid var(--line);border-radius:9px;display:flex;align-items:center;gap:8px;padding:0 12px;color:#9aa1af;font-size:13px}.admin-pill{height:38px;border:1px solid var(--line);border-radius:20px;padding:0 14px;display:flex;align-items:center;gap:8px;font-size:13px}.admin-content{padding:30px;overflow:auto}.admin-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:24px}.admin-heading h1{margin:0;font-size:25px;letter-spacing:-.03em}.admin-heading p{margin:7px 0 0;color:var(--muted);font-size:13px}.admin-btn{display:inline-block;padding:11px 16px;background:#168fd4;color:#fff;border:0;border-radius:8px;font-weight:700;font-size:13px}.admin-card{background:#fff;border:1px solid var(--line);border-radius:17px;padding:20px}.admin-table{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:auto}.admin-table table{border-collapse:collapse;width:100%;min-width:800px}.admin-table th,.admin-table td{text-align:left;padding:15px;border-bottom:1px solid #edf0f4;vertical-align:top}.admin-table th{font-size:12px;text-transform:uppercase;color:#69778d;letter-spacing:.04em}.admin-empty{color:var(--muted)}.admin-form-card{max-width:780px}.admin-form-card label{display:block;font-weight:600;margin:17px 0 7px}.admin-form-card input,.admin-form-card select,.admin-form-card textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #b9c2d0;border-radius:7px;font:inherit}.admin-form-card textarea{min-height:110px;resize:vertical}.admin-error{background:#fff0f0;color:#a32121;padding:12px;border-radius:7px;margin-bottom:15px}@media(max-width:780px){.admin-sidebar{width:64px;padding:18px 8px}.admin-logo{font-size:0;justify-content:center;padding:5px 0 28px}.admin-nav-label,.admin-nav a span:not(.admin-icon),.admin-sidebar-bottom>div:not(.admin-avatar){display:none}.admin-nav a{justify-content:center;padding:11px 6px}.admin-badge{display:none}.admin-sidebar-bottom{justify-content:center}.admin-topbar{padding:0 15px}.admin-top-title,.admin-pill{display:none}.admin-search{margin-left:0;width:100%}.admin-content{padding:21px 15px}.admin-heading{display:block}.admin-heading .admin-btn{margin-top:15px}}
</style>
